/* style settings */

.style-settings-container .themed-color-wrapper {
  display: flex;
  gap: var(--size-4-2);
}

.style-settings-container .themed-color-wrapper>div+div {
  margin-top: 0;
}

.style-settings-container {
  margin-left: var(--size-4-1);
  padding-left: var(--size-4-8);
  border-left: 1px solid var(--divider-color);
}

/* printing */

@media print {
  .theme-light {
    --blockquote-background-color: rgba(var(--bg_dark_x), 0.25);
    --code-background: rgba(var(--bg_highlight_dark_x), 0.25);
    --table-header-background: rgba(var(--bg_dark2_x), 0.25);
  }
}


